"""Build a portable before/after viewer and evidence-backed Russian report."""
import json

from common import ROOT,config,read_json


def main():
    out=ROOT/"runs/reflections"
    summary=read_json(out/"filter_summary.json")
    ev=read_json(out/"evaluation.json")
    kinds={"direct":"Настоящий человек","reflection":"Отражение","not_person":"Не человек","uncertain":"Неясно"}
    metrics="".join(f'<tr><td>{kinds[r["label"]]}</td><td>{r["annotated_boxes"]}</td><td>{r["input_boxes_removed"]}</td><td>{r["track_coverage"]["bytetrack"]["before_covered"]} → {r["track_coverage"]["bytetrack"]["after_covered"]}</td><td>{r["track_coverage"]["botsort_reid"]["before_covered"]} → {r["track_coverage"]["botsort_reid"]["after_covered"]}</td></tr>' for r in ev["summary"])
    counts="".join(f'<tr><td>{r["video"]}</td><td>{r["suppressed_detection_samples"]}</td><td>{r["accepted_intervals"]}</td><td>{r["model_seconds"]:.1f}</td></tr>' for r in summary)
    human="".join(f'<tr><td><a href="review/{r["review_id"]}.jpg">{r["review_id"]}</a></td><td>{r["video"]}, {r["t"]} с</td><td>{kinds[r["label"]]}</td><td>{"Удалена" if r["input_detection_removed"] else "Сохранена"}</td></tr>' for r in ev["human_outcomes"])
    options="".join(f'<option>{v}</option>' for v in config()["videos"])
    page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Фильтр отражений — до и после</title><style>:root{font:16px/1.55 system-ui;color:#1c2832;background:#f5f6f7}body{max-width:1160px;margin:30px auto;padding:0 20px}h1{font-size:28px}h2{font-size:21px;margin-top:30px}.note{background:#fff4dc;border-left:4px solid #b7791f;padding:12px 18px}select,button{font:inherit;padding:8px;margin:5px;background:white;border:1px solid #b7c1ca;border-radius:4px}video{width:100%;max-height:78vh;background:#15171a}table{width:100%;border-collapse:collapse;background:white}td,th{padding:10px;border-bottom:1px solid #dde2e6;text-align:left}a{color:#075e9c}.small{font-size:14px;color:#51616e}.scroll{overflow:auto}</style>
<h1>Автоматический фильтр отражений: до и после</h1>
<p>Слева — исходный трекинг; справа — фильтрация и полный повторный запуск выбранного трекера. Роли используют прежние наблюдения Qwen: ошибки «банкир/клиент» здесь не исправлялись.</p>
<p class="note">Проверка на тех же четырёх роликах. Это разработка и диагностика, не независимый тест надёжности. Неизвестные случаи сохраняются. Красные рамки справа — исключённые детекции для проверки решения, они не являются активными треками.</p>
<div><label>Видео <select id="clip">OPTIONS</select></label><label>Трекер <select id="tracker"><option value="bytetrack">ByteTrack</option><option value="botsort_reid">BoT-SORT + ReID</option></select></label><button id="slow">0,5×</button><button id="normal">1×</button><a id="download" download>Скачать MP4</a></div><video id="video" controls preload="metadata" playsinline></video><div id="times"></div>
<h2>Не потеряли ли настоящих людей</h2><p>Аудит 24 выбранных кадров: шесть меток пользователя и визуальная разметка остальных рамок ассистентом. Числа относятся к размеченным рамкам, а не уникальным людям. Покрытие трекером — наличие рамки с IoU ≥ 0,5. Это проверка сохранения известных детекций, а не полнота обнаружения всех людей.</p><div class="scroll"><table><thead><tr><th>Метка</th><th>Проверено рамок</th><th>Удалено входных</th><th>ByteTrack до → после</th><th>BoT-SORT до → после</th></tr></thead><tbody>METRICS</tbody></table></div>
<h2>Ваши шесть контрольных случаев</h2><table><thead><tr><th>Кадр</th><th>Видео</th><th>Ваша метка</th><th>Решение фильтра</th></tr></thead><tbody>HUMAN</tbody></table><p><a href="review/index.html">Открыть кадры крупнее</a> · <a href="review/human_labels.json">Сохранённые метки пользователя</a></p>
<h2>Объём фильтрации и вычислений</h2><table><thead><tr><th>Видео</th><th>Удалено рамок × кадров</th><th>Принято интервалов</th><th>Генерация модели, с</th></tr></thead><tbody>COUNTS</tbody></table><p class="small">Рамки × кадры не равны людям. Интервалы могут иметь общую границу; удалённые рамки считаются один раз. Время генерации не включает загрузку модели, декодирование, трекеры и рендер.</p>
<h2>Как принято решение</h2><p>Каждые две секунды Qwen проверяет размеченные детектором силуэты в контексте полного кадра: настоящий человек, отражение или неясно. Для отражения нужны видимая отражающая поверхность и соответствующий настоящий человек. Удаление допускается только между двумя согласованными наблюдениями одной пары предварительных ByteTrack ID, без пропусков и скачков рамок. Пересекающиеся тела сохраняются. Любой ответ «настоящий человек» защищает этот предварительный ID во всём ролике.</p><p>Это офлайн-фильтр: он использует будущий кадр и проверку всей истории ID. Это не готовый потоковый алгоритм. Согласие одной модели не является независимым доказательством; модель может ошибаться в выборе соответствующего человека. Ручных зон и меток пользователя на входе нет. Оба итоговых трекера используют один и тот же фильтр, построенный на предварительных дорожках ByteTrack.</p>
<p><a href="REPORT.md">Полный отчёт</a> · <a href="evaluation.json">Каждая проверенная рамка</a> · <a href="filter_summary.json">Сводка фильтра</a> · <a href="../index.html">Первое сравнение трекеров</a></p>
<script>const clip=document.getElementById('clip'),tracker=document.getElementById('tracker'),video=document.getElementById('video');const moments={'X-4':[0,2,4,10,15,20,50,60],'X-18':[0,10,12.5,13.6,18,20],'X-27':[0,10,17,19,21,23],'X-38':[0,10,20,30,36,40]};function update(){video.src=`${clip.value}/${clip.value}-${tracker.value}-before-after.mp4`;document.getElementById('download').href=video.src;document.getElementById('times').replaceChildren();for(const t of moments[clip.value]){const b=document.createElement('button');b.textContent=t+' с';b.onclick=()=>{video.currentTime=t;video.pause()};document.getElementById('times').append(b)}}clip.onchange=update;tracker.onchange=update;document.getElementById('slow').onclick=()=>video.playbackRate=.5;document.getElementById('normal').onclick=()=>video.playbackRate=1;update();</script></html>'''
    conflict=ev["post_run_model_conflict"]
    if conflict["model_observation"] and conflict["model_observation"]["kind"]=="reflection":
        outcome="удалена — это опасная ошибка" if conflict["input_detection_removed"] else "сохранена фильтром"
        diagnostic=f'<h2>Опасная ошибка самой модели</h2><p>На X-18 в 6 с Qwen назвал входящего клиента D0 отражением. По последовательности кадров это настоящий человек; вывод проверен визуально ассистентом. Его исходная детекция {outcome}. Этот дополнительный разбор выбран после результатов и не входит в таблицу 24 кадров.</p><p><a href="X-18/frames/000060.jpg">Посмотреть до/после на 6 с</a></p>'
        page=page.replace('<h2>Объём фильтрации и вычислений</h2>',diagnostic+'<h2>Объём фильтрации и вычислений</h2>')
    for key,value in [("OPTIONS",options),("METRICS",metrics),("HUMAN",human),("COUNTS",counts)]: page=page.replace(key,value)
    (out/"index.html").write_text(page)
    lines=["# Автоматический фильтр отражений — до/после","","[Открыть видео](index.html)","","Четыре исходных ролика, 1 807 кадров при 10 fps. Общие исходные детекции сохранены без изменений. Фильтрация выполнена автоматически без ручных зон и без меток пользователя на входе. После неё повторно запущены оба трекера с прежними настройками.","","## Сохранение настоящих людей","",ev["scope"],"","| Метка | Проверено рамок | Удалено входных | ByteTrack до/после | BoT-SORT до/после |","|---|---:|---:|---:|---:|"]
    for r in ev["summary"]:
        b=r["track_coverage"]["bytetrack"];s=r["track_coverage"]["botsort_reid"]
        lines.append(f'| {kinds[r["label"]]} | {r["annotated_boxes"]} | {r["input_boxes_removed"]} | {b["before_covered"]}/{b["after_covered"]} | {s["before_covered"]}/{s["after_covered"]} |')
    lines.extend(["","Проверка относится к выбранным исходным рамкам. Не найдённые исходным детектором люди не входят в знаменатель. Частичная рамка и полная рамка могут описывать одного человека. Это не общая полнота, IDF1 или HOTA.","","## Метки пользователя","","| Случай | Эталон пользователя | Решение |","|---|---|---|"])
    for r in ev["human_outcomes"]: lines.append(f'| [{r["review_id"]}](review/{r["review_id"]}.jpg) | {kinds[r["label"]]} | {"Удалена" if r["input_detection_removed"] else "Сохранена"} |')
    lines.extend(["","Метки сохранены до вычисления итоговой оценки и не использованы при фильтрации или подборе порогов. R6 — не человек; он не обязан быть отражением. Универсальная фильтрация всех ложных детекций в этот эксперимент не входит.","","## Алгоритм и ограничения","","1. Qwen3.5-9B с прежними зафиксированными весами видит полный кадр и D-рамки каждые 2 секунды. Он классифицирует силуэт и указывает соответствующего настоящего человека для отражения.","2. Два соседних наблюдения должны назвать одну и ту же пару предварительных ByteTrack ID; поверхность должна быть отмечена как отражающая. Пропуск, сильное пересечение рамок или скачок движения запрещает удаление всего интервала.","3. Любая классификация ID как настоящего человека защищает его на всём видео. Неясные и неразобранные ответы сохраняют исходные детекции.","4. Фильтр создаёт новый кэш с индексами исходных детекций. Оба трекера запускаются заново. Прежние наблюдения ролей применяются по исходным индексам — ошибки определения ролей остаются.","","Фильтр офлайн: использует будущие кадры и глобальное вето по истории. Для потокового применения это поведение нужно отдельно пересмотреть и проверить. Это сравнение двух итоговых трекеров после фильтра, использующего предварительный ByteTrack; влияние выбора предварительного трекера не изолировано. Согласие Qwen не является калиброванной уверенностью. Геометрические пороги — заранее выбранные защитные эвристики, не обученные гарантии.","","## Вычисления","","| Видео | Удалено рамок × кадров | Принято интервалов | Генерация модели, с |","|---|---:|---:|---:|"])
    for r in summary: lines.append(f'| {r["video"]} | {r["suppressed_detection_samples"]} | {r["accepted_intervals"]} | {r["model_seconds"]:.1f} |')
    lines.extend(["","Удалённые рамки считаются без повторов по границам интервалов. Эти счётчики не равны числу людей. Время генерации исключает загрузку модели, декодирование, трекеры и рендер.","","## Воспроизводимость","","Новые результаты находятся в `runs/reflections/`; исходный прогон не перезаписан. В каждом видео сохранены исходные ответы модели, новый кэш детекций, причины удаления и оба повторных трекинга. Метки находятся отдельно в `reflection_human_labels.json` и `reflection_assistant_labels.json` и читаются только оценщиком.","","[Оценка каждой рамки](evaluation.json), [сводка](filter_summary.json), [шесть эталонных меток](review/human_labels.json). Модель: [Qwen3.5-9B](https://huggingface.co/Qwen/Qwen3.5-9B)."])
    lines.extend(["","## Отдельная ошибка модели на X-18, 6 с","",f'Модель выдала: `{json.dumps(conflict["model_observation"],ensure_ascii=False)}`. На исходной последовательности виден входящий настоящий клиент; визуальная проверка ассистентом. Исходная детекция удалена: **{conflict["input_detection_removed"]}**. Покрытие после повторного трекинга: `{conflict["after_covered"]}`. Это дополнительный разбор после результатов, не часть фиксированной таблицы 24 кадров.',"","[Кадр до/после](X-18/frames/000060.jpg)","","## ID после перекрытия, X-18","","Числа ID между отдельными запусками не обязаны совпадать. Сравнивать нужно сохранение/возврат ID внутри каждого запуска.","","| Время | ByteTrack до | ByteTrack после | BoT-SORT до | BoT-SORT после |","|---|---|---|---|---|"])
    for row in ev["occlusion_case_X18"]: lines.append(f'| {row["t"]} | {row["bytetrack"]["before"]} | {row["bytetrack"]["after"]} | {row["botsort_reid"]["before"]} | {row["botsort_reid"]["after"]} |')
    (out/"REPORT.md").write_text("\n".join(lines)+"\n")
    print(out/"index.html")


if __name__=="__main__": main()
